  document.getElementById('report-meta').textContent = meta.filter(Boolean).join(' · ');
  try { renderSummary(r); } catch (sumErr) { var sb = document.getElementById('report-summary'); if (sb) sb.innerHTML = ''; }
  try { renderWeekAttention(r.weekAttention); } catch (attnErr) { var ab = document.getElementById('report-attention'); if (ab) ab.innerHTML = ''; }
  var dname = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'][r.dow];
  var dshort = dname ? dname.slice(0, 3) : '';
