  if (src.wholesale && !src.wholesale.ok) h.push('<div class="rp-card"><h3>WHOLESALE ' + badge('st-red', '✕', 'Read error') + '</h3><p class="rp-note">' + esc(src.wholesale.error) + ' — this is a read problem, not missing data.</p></div>');
